files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: #e0e0e0;
  padding: 1rem;
}

.card {
  background: #16213e;
  border-radius: 16px;
  padding: 2rem 1.5rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  text-align: center;
  width: 100%;
  max-width: 360px;
  border: 2px solid #0f3460;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  color: #e94560;
  letter-spacing: 1px;
}

.light-housing {
  background: #0f0f1a;
  border-radius: 12px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
  border: 2px solid #0f3460;
}

.lamp {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: #2a2a3a;
  transition: background 0.15s ease, box-shadow 0.15s ease;
  border: 3px solid #1a1a2e;
}

.lamp.red.active {
  background: #e94560;
  box-shadow: 0 0 20px #e94560, 0 0 40px #e94560;
}

.lamp.amber.active {
  background: #f5a623;
  box-shadow: 0 0 20px #f5a623, 0 0 40px #f5a623;
}

.lamp.green.active {
  background: #2ecc71;
  box-shadow: 0 0 20px #2ecc71, 0 0 40px #2ecc71;
}

.status {
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
  color: #a0a0b0;
  min-height: 1.5em;
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.75rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  min-width: 120px;
}

.btn.start {
  background: #2ecc71;
  color: #0f0f1a;
}

.btn.start:hover:not(:disabled) {
  background: #27ae60;
}

.btn.stop {
  background: #e94560;
  color: #fff;
}

.btn.stop:hover:not(:disabled) {
  background: #c0392b;
}

.btn:focus-visible {
  outline: 3px solid #f5a623;
  outline-offset: 3px;
}

.btn:active:not(:disabled) {
  transform: scale(0.96);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  .lamp {
    width: 64px;
    height: 64px;
  }
  .btn {
    min-width: 100px;
    padding: 0.65rem 1.25rem;
  }
}

(function () {
  'use strict';

  var lamps = {
    red: document.getElementById('redLamp'),
    amber: document.getElementById('amberLamp'),
    green: document.getElementById('greenLamp')
  };
  var statusLabel = document.getElementById('statusLabel');
  var startBtn = document.getElementById('startBtn');
  var stopBtn = document.getElementById('stopBtn');

  var state = {
    running: false,
    current: null,
    timer: null
  };

  var CYCLE = [
    { color: 'red', duration: 3000, label: 'Red' },
    { color: 'green', duration: 3000, label: 'Green' },
    { color: 'amber', duration: 1000, label: 'Amber' }
  ];

  function render() {
    for (var key in lamps) {
      if (lamps.hasOwnProperty(key)) {
        lamps[key].classList.toggle('active', state.current === key);
      }
    }
    if (!state.running) {
      statusLabel.textContent = 'Current: Idle';
    } else {
      var active = CYCLE.filter(function (c) { return c.color === state.current; })[0];
      statusLabel.textContent = 'Current: ' + (active ? active.label : 'Idle');
    }
  }

  function clearTimer() {
    if (state.timer !== null) {
      clearTimeout(state.timer);
      state.timer = null;
    }
  }

  function step(index) {
    if (!state.running) return;
    var phase = CYCLE[index % CYCLE.length];
    state.current = phase.color;
    render();
    state.timer = setTimeout(function () {
      step(index + 1);
    }, phase.duration);
  }

  function start() {
    if (state.running) return;
    state.running = true;
    startBtn.disabled = true;
    stopBtn.disabled = false;
    step(0);
  }

  function stop() {
    if (!state.running) return;
    state.running = false;
    state.current = null;
    clearTimer();
    startBtn.disabled = false;
    stopBtn.disabled = true;
    render();
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);

  render();
})();
